import { VirtualList, type VirtualListChangeDetail } from '@absoluteui/components/virtual-list';

interface Person { id: string; name: string }
const people: Person[] = Array.from({ length: 100_000 }, (_, i) => ({ id: `p${String(i)}`, name: `Person ${String(i + 1)}` }));
const host = document.createElement('div');
document.body.append(host);
const list = VirtualList.create<Person>(host, {
  label: 'People',
  items: people,
  selection: 'multiple',
  itemKey: (p) => p.id,
  itemText: (p) => p.name,
  renderItem: (p) => document.createTextNode(p.name),
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<VirtualListChangeDetail>).detail;
  host.dataset.selected = String(value.length);
});
list.scrollToIndex(5000, 'center');

import { VirtualList } from '@absoluteui/components/virtual-list';

const host = document.createElement('div');
document.body.append(host);
let items: string[] = [];
const list = VirtualList.create<string>(host, {
  label: 'Activity',
  items,
  variableHeight: true,
  renderItem: (text) => {
    const p = document.createElement('p');
    p.textContent = text;
    return p;
  },
  loadMore: async () => {
    const page = await Promise.resolve(Array.from({ length: 50 }, (_, i) => `Event ${String(items.length + i + 1)}`));
    items = [...items, ...page];
    list.update({ items, hasMore: items.length < 500 });
  },
});
